}
button:hover { border-color: var(--accent); }
button.primary, #add-submit { background: var(--accent); border-color: var(--accent); color: #fff; font-weight: 600; }
button.danger { color: var(--danger); border-color: var(--danger); }

.error-msg { color: var(--danger); margin: 10px 0 0; font-size: 0.9rem; }

/* Controls */
.controls { display: flex; gap: 8px; margin-bottom: 16px; }
.controls #search { flex: 1; }
.controls #tag-filter { max-width: 180px; }

/* List */
.list { display: grid; gap: 14px; }
.card {
  display: grid; grid-template-columns: 120px 1fr auto; gap: 14px;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius); overflow: hidden; align-items: start;
}
.preview { width: 120px; height: 90px; object-fit: cover; background: var(--surface-2); }
.preview.placeholder { display: block; background: linear-gradient(135deg, #232733, #2e333f); }
.card-body { padding: 12px 0; min-width: 0; }
.card-title { margin: 0 0 4px; font-size: 1.05rem; display: flex; align-items: center; gap: 6px; }
.card-title a { color: var(--text); text-decoration: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card-title a:hover { color: var(--accent); text-decoration: underline; }
.favicon { width: 16px; height: 16px; flex: 0 0 16px; border-radius: 3px; }
.card-url { margin: 0 0 6px; color: var(--muted); font-size: 0.82rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card-desc { margin: 0 0 6px; font-size: 0.9rem; color: #c7ccd6; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.card-notes { margin: 4px 0 0; font-size: 0.85rem; color: var(--muted); }
.card-meta { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; align-items: center; }
.card-actions { padding: 12px 12px 0 0; }
.edit-btn { padding: 6px 10px; }

.tag { background: var(--surface-2); border: 1px solid var(--border); border-radius: 999px; padding: 2px 10px; font-size: 0.78rem; color: #c7ccd6; }
.badge { font-size: 0.75rem; padding: 2px 8px; border-radius: 999px; }
.badge.fetching { background: rgba(91, 141, 239, 0.15); color: var(--accent); }
.badge.failed { background: rgba(229, 72, 77, 0.12); color: var(--danger); }

.empty-state { text-align: center; color: var(--muted); padding: 48px 16px; border: 1px dashed var(--border); border-radius: var(--radius); }

/* Edit dialog */
.edit-dialog { background: var(--surface); color: var(--text); border: 1px solid var(--border); border-radius: var(--radius); width: min(520px, 92vw); padding: 20px; }
.edit-dialog::backdrop { background: rgba(0, 0, 0, 0.55); }
.edit-dialog h2 { margin: 0 0 16px; }
.edit-dialog label { display: block; margin-bottom: 12px; font-size: 0.85rem; color: var(--muted); }
.edit-dialog label input, .edit-dialog label textarea { margin-top: 4px; }
.edit-actions { display: flex; align-items: center; gap: 8px; margin-top: 8px; }
.edit-actions .spacer { flex: 1; }

@media (max-width: 560px) {
  .card { grid-template-columns: 1fr; }
  .preview { width: 100%; height: 140px; }
  .card-actions { padding: 0 12px 12px; }
}
